  "inlineSchema": "// Prisma Schema file cho NestJS Core Framework (Enterprise Auth, Team/Department, Role & Direct Permission)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// 1. Model Phòng Ban / Team (Department)\nmodel Department {\n  id          String   @id @default(uuid())\n  code        String   @unique\n  name        String\n  description String?\n  parentId    String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  parent   Department?  @relation(\"DepartmentHierarchy\", fields: [parentId], references: [id], onDelete: SetNull)\n  children Department[] @relation(\"DepartmentHierarchy\")\n\n  users UserDepartment[]\n\n  @@map(\"departments\")\n}\n\n// 2. Model Người Dùng (User)\nmodel User {\n  id                 String    @id @default(uuid())\n  email              String    @unique\n  password           String\n  name               String\n  avatar             String?\n  phone              String?\n  identityCard       String?   @map(\"identity_card\")\n  gender             String?\n  dateOfBirth        DateTime? @map(\"date_of_birth\")\n  address            String?   @db.Text\n  bio                String?   @db.Text\n  isActive           Boolean   @default(true)\n  twoFactorSecret    String?   @map(\"two_factor_secret\")\n  isTwoFactorEnabled Boolean   @default(false) @map(\"is_two_factor_enabled\")\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  roles       UserRole[]\n  permissions UserPermission[] // Gán Permission TRỰC TIẾP cho User\n  departments UserDepartment[]\n  sessions    UserSession[]\n\n  @@map(\"users\")\n}\n\n// 2.1 Model Phiên Đăng Nhập Đa Thiết Bị (Multi-Device User Sessions)\nmodel UserSession {\n  id        String   @id @default(uuid())\n  userId    String   @map(\"user_id\")\n  tokenHash String   @map(\"token_hash\") @db.Text\n  userAgent String?  @map(\"user_agent\")\n  ipAddress String?  @map(\"ip_address\")\n  isRevoked Boolean  @default(false) @map(\"is_revoked\")\n  expiresAt DateTime @map(\"expires_at\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"user_sessions\")\n}\n\n// 3. Model Vai Trò (Role - Ví dụ: Admin, Manager, Accountant)\nmodel Role {\n  id          String   @id @default(uuid())\n  code        String   @unique // 'super-admin', 'admin', 'manager'\n  name        String\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  users       UserRole[]\n  permissions RolePermission[]\n\n  @@map(\"roles\")\n}\n\n// 4. Model Quyền Hạn (Permission - Ví dụ: employee:read, employee:create)\nmodel Permission {\n  id          String   @id @default(uuid())\n  code        String   @unique // 'employee:read', 'employee:create'\n  name        String\n  module      String // 'employee', 'account', 'order'\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  roles RolePermission[]\n  users UserPermission[] // Gán Permission TRỰC TIẾP cho User\n\n  @@map(\"permissions\")\n}\n\n// 5. Bảng trung gian Gắn User theo Role (User -> Roles)\nmodel UserRole {\n  userId String\n  roleId String\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role Role @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  @@id([userId, roleId])\n  @@map(\"user_roles\")\n}\n\n// 6. Bảng trung gian Gắn Permission TRỰC TIẾP cho User (User -> Direct Permissions)\nmodel UserPermission {\n  userId       String\n  permissionId String\n\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@id([userId, permissionId])\n  @@map(\"user_permissions\")\n}\n\n// 7. Bảng trung gian Gắn Permission vào Role (Role -> Permissions)\nmodel RolePermission {\n  roleId       String\n  permissionId String\n\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, permissionId])\n  @@map(\"role_permissions\")\n}\n\n// 8. Bảng trung gian Gắn User vào Phòng ban / Team (User -> Departments)\nmodel UserDepartment {\n  userId       String\n  departmentId String\n  isPrimary    Boolean @default(false)\n\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  department Department @relation(fields: [departmentId], references: [id], onDelete: Cascade)\n\n  @@id([userId, departmentId])\n  @@map(\"user_departments\")\n}\n\n// 9. Model Quản Lý File / Media (Media Manager)\nmodel Media {\n  id          String   @id @default(uuid())\n  filename    String\n  filepath    String\n  url         String\n  mimetype    String\n  size        Int\n  disk        String   @default(\"local\")\n  title       String?\n  altText     String?\n  caption     String?\n  description String?\n  createdById String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"media\")\n}\n\n// 10. Model Cấu Hình Hệ Thống (Global Options - wp_options Architecture)\nmodel Option {\n  id          String   @id @default(uuid())\n  optionName  String   @unique @map(\"option_name\")\n  optionValue String?  @map(\"option_value\") @db.Text\n  autoload    Boolean  @default(true)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"options\")\n}\n",
